import java.util.*;

class Solution {
  public int[] maximumSumQueries(int[] nums1, int[] nums2, int[][] queries) {
    int n = nums1.length, qn = queries.length;
    int[] coords = nums2.clone();
    Arrays.sort(coords);
    int unique = 0;
    for (int v : coords) if (unique == 0 || coords[unique - 1] != v) coords[unique++] = v;
    int size = 1;
    while (size < unique) size <<= 1;
    int[] tree = new int[size << 1];
    Arrays.fill(tree, -1);
    int[][] pairs = new int[n][2];
    for (int i = 0; i < n; i++) pairs[i] = new int[] {nums1[i], nums2[i]};
    Arrays.sort(pairs, (a, b) -> Integer.compare(b[0], a[0]));
    int[][] qs = new int[qn][3];
    for (int i = 0; i < qn; i++) qs[i] = new int[] {queries[i][0], queries[i][1], i};
    Arrays.sort(qs, (a, b) -> Integer.compare(b[0], a[0]));
    int[] ans = new int[qn];
    Arrays.fill(ans, -1);
    int at = 0;
    for (int[] query : qs) {
      while (at < n && pairs[at][0] >= query[0]) {
        int pos = Arrays.binarySearch(coords, 0, unique, pairs[at][1]);
        int node = size + pos, value = pairs[at][0] + pairs[at][1];
        tree[node] = Math.max(tree[node], value);
        for (node >>= 1; node > 0; node >>= 1)
          tree[node] = Math.max(tree[node << 1], tree[(node << 1) | 1]);
        at++;
      }
      int pos = lowerBound(coords, unique, query[1]);
      if (pos < unique) ans[query[2]] = rangeMax(tree, size, pos, unique - 1);
    }
    return ans;
  }

  private int lowerBound(int[] a, int n, int target) {
    int lo = 0, hi = n;
    while (lo < hi) {
      int mid = (lo + hi) >>> 1;
      if (a[mid] < target) lo = mid + 1;
      else hi = mid;
    }
    return lo;
  }

  private int rangeMax(int[] tree, int size, int left, int right) {
    int result = -1;
    left += size;
    right += size;
    while (left <= right) {
      if ((left & 1) == 1) result = Math.max(result, tree[left++]);
      if ((right & 1) == 0) result = Math.max(result, tree[right--]);
      left >>= 1;
      right >>= 1;
    }
    return result;
  }
}
